#!/bin/sh
# PreToolUse (Edit|Write): generated files are rebuilt by their script, never edited by hand.
# Reads the tool call as JSON on stdin; exit 2 blocks and sends stderr back to Claude.
path=$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("tool_input",{}).get("file_path",""))' 2>/dev/null)
case "$path" in
  */lib/logoFiles.ts|*/public/logos/*)
    echo "$path is generated by scripts/make-logos.mjs. Edit content/logos.json and run: node scripts/make-logos.mjs (or: node scripts/make-logos.mjs add \"Company\" [domain]). See .claude/rules/logos.md." >&2
    exit 2 ;;
  */public/pagefind/*)
    echo "$path is generated by Pagefind at build time. Do not edit it." >&2
    exit 2 ;;
esac
exit 0
